mapper.select:
select tmt.id, tmt.mix_area, tmt.glue, tmm.machine_name,tmm.MACHINE_CODE , tmt.winter_mix_time, tmt.summer_mix_time, tmt.interval_time, tmt.remark, tmt.del_flag, tmt.create_by, tmt.create_time, tmt.update_by, tmt.update_time from t_mixing_time tmt left join T_MIX_MACHINE tmm on tmt.MIX_AREA=tmm.MIX_AREA and tmt.MACHINE_CODE=tmm.MACHINE_CODE and tmm.DEL_FLAG='0' where tmt.del_flag = '0' and tmt.mix_area = #{mixArea} and INSTR(tmt.glue, #{glue}) > 0
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType= VARCHAR} MIX_AREA,#{data.glue,jdbcType= VARCHAR} GLUE,#{data.machineCode,jdbcType= VARCHAR} MACHINE_CODE,#{data.machineName,jdbcType= VARCHAR} MACHINE_NAME
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_mixing_time m inner join temp_table t on m.MIX_AREA = t.MIX_AREA and m.GLUE = t.GLUE and ((t.MACHINE_NAME is null and m.MACHINE_CODE is null) or ( t.MACHINE_CODE is not null and m.MACHINE_CODE = t.MACHINE_CODE)) and m.del_flag ='0'

mapper.insert:
insert into t_mixing_time (id,mix_area,glue,machine_code,winter_mix_time,summer_mix_time,interval_time,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{mixingTime.mixArea,jdbcType= VARCHAR} mix_area, #{mixingTime.glue,jdbcType= VARCHAR} glue, #{mixingTime.machineCode,jdbcType= VARCHAR} machine_code, #{mixingTime.winterMixTime,jdbcType=DOUBLE} winter_mix_time, #{mixingTime.summerMixTime,jdbcType=DOUBLE} summer_mix_time, #{mixingTime.intervalTime,jdbcType=DOUBLE} interval_time, #{mixingTime.remark,jdbcType= VARCHAR} remark, #{mixingTime.delFlag,jdbcType= VARCHAR} del_flag, #{mixingTime.createBy,jdbcType= VARCHAR} create_by, #{mixingTime.createTime,jdbcType=TIMESTAMP} create_time, #{mixingTime.updateBy,jdbcType= VARCHAR} update_by, #{mixingTime.updateTime,jdbcType=TIMESTAMP} update_time
) x

mapper.select:
WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.mixArea,jdbcType= VARCHAR} MIX_AREA,#{data.machineName,jdbcType= VARCHAR} MACHINE_NAME
) select m.MACHINE_CODE from T_MIX_MACHINE m right join temp_table t on m.MIX_AREA = t.MIX_AREA and m.MACHINE_NAME = t.MACHINE_NAME and m.del_flag ='0' order by t.row_numbers
